async function buildControlImage(){if(!controlRaw){controlImage=null;$("control-preview").hidden=true;return;}const mode=$("control-preprocess").value;if(mode==="none"){controlImage=controlRaw;$("control-preview").src=controlImage;$("control-preview").hidden=false;$("control-image-status").textContent="ControlNet-referentie klaar (origineel).";return;}const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=controlRaw;});const scale=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d",{willReadFrequently:true});ctx.drawImage(img,0,0,w,h);const src=ctx.getImageData(0,0,w,h),gray=new Float32Array(w*h),out=ctx.createImageData(w,h),threshold=Number($("control-edge-threshold").value)||80;for(let i=0;i<w*h;i++){const p=i*4;gray[i]=.299*src.data[p]+.587*src.data[p+1]+.114*src.data[p+2];}for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){const i=y*w+x,gx=-gray[i-w-1]+gray[i-w+1]-2*gray[i-1]+2*gray[i+1]-gray[i+w-1]+gray[i+w+1],gy=-gray[i-w-1]-2*gray[i-w]-gray[i-w+1]+gray[i+w-1]+2*gray[i+w]+gray[i+w+1],v=Math.hypot(gx,gy)>=threshold?255:0,p=i*4;out.data[p]=out.data[p+1]=out.data[p+2]=v;out.data[p+3]=255;}ctx.putImageData(out,0,0);controlImage=c.toDataURL("image/png");$("control-preview").src=controlImage;$("control-preview").hidden=false;$("control-image-status").textContent="Sobel edge map gemaakt ("+w+"×"+h+").";}
$("control-image").addEventListener("change",async e=>{const f=e.target.files[0];if(!f){controlRaw=null;controlImage=null;$("control-preview").hidden=true;return;}if(f.size>16*1024*1024)return toast("ControlNet-afbeelding mag maximaal 16 MB zijn");try{controlRaw=await readData(f);await buildControlImage();}catch(err){controlRaw=null;controlImage=null;$("control-preview").hidden=true;toast(err.message);}});
