async function buildMaskPayload(){const raw=sourceMask||(maskHasMarks?$("mask-canvas").toDataURL("image/png"):null);if(!raw)return null;if(!$("mask-invert").checked)return raw;const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=raw;});const c=document.createElement("canvas");c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext("2d");ctx.drawImage(img,0,0);const p=ctx.getImageData(0,0,c.width,c.height);for(let i=0;i<p.data.length;i+=4){const v=255-Math.round(.299*p.data[i]+.587*p.data[i+1]+.114*p.data[i+2]);p.data[i]=p.data[i+1]=p.data[i+2]=v;p.data[i+3]=255;}ctx.putImageData(p,0,0);return c.toDataURL("image/png");}
